def main():
    sys.stdout.reconfigure(encoding='utf-8');resources=resource_gate();OUT.mkdir(exist_ok=False);path=OUT/'attempt_01.json';protocol=ROOT/'MC_RC_GLOBAL_LOCAL_TASK_CPU_PLAN_2026-10-03.md';support=ROOT/'experiments/mc_rc_global_local_task_cpu_support.py';prepfile=ROOT/'experiments/mc_rc_current_development_input_preparation/attempt_01.json';pf=ROOT/'experiments/mc_rc_development_training_input_cpu/attempt_01.json';proof=pf.parent/'independent_all19_observed_inputs_and_label_axes_attempt_01.json';prep=read(prepfile);production=read(pf);q=read(proof);assert all(x['complete'] and not x['errors'] for x in (prep,production,q));cases=prep['cases'];assert len(cases)==19 and {x['patient'] for x in cases}==DEVELOPERS;by={x['uid']:x for x in production['series']}
