                h=dict(update=step+1,last100_loss_mean=np.mean(losses[-100:],axis=0).tolist(),lr=lr,training_elapsed_seconds=time.perf_counter()-t,last_patient=patient,last_sample=sample);r['training_history'].append(h);write(path,r);print(json.dumps(h),flush=True)
